// build/ext-bundle.js — 给 iOS 系统翻译扩展裁一份翻译引擎（learning-design §9.9）。
//
// 产物：`dist-app/ExtEngine.js`，一个文件，由原生在 JavaScriptCore 里 `evaluateScript`
// 一次。为什么是**同一份字节**而不是 Swift 重写一遍，见 `app/ext-shim.js` 的文件头与
// domain-design §2.6 规则 2：传输那一层每一处调参都要两份同时改，而漂开的症状是
// 「Mac 上好好的，iPhone 上少一个字段」，没有一行日志会说。
//
// 与 `build/app-bundle.js` 的关系：同一个做法（按顺序拼 IIFE、生成物跟着 flavor 走），
// 但**清单短得多** —— App 包要渲染整个界面，这里只要「把一段文字翻出来」。多带一个
// 模块就是多带一份到手机上的死重，而扩展进程的内存上限比 App 紧得多。
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

// 顺序即依赖。垫片必须第一 —— 后面几个在**加载期**就读 `chrome`。
// 这份清单是逐文件 grep 出来的最小集，不是「把 content/ 都拿来」：
//   ext-shim        window / chrome.storage / fetch / 定时器 / AbortController
//   —— 故意**不带** i18n-messages（1 MB 的全部语种文案）与 translation-core（33 KB 的字幕引擎）：
//      translation-api 对 TranslationCore 是刻意零依赖的（见它自己 363 行那段注释：设置页加载它
//      却不加载 core，在那儿调 t() 会抛 ReferenceError）。失败文案由**原生按 code 查表**给，
//      与 Mac 面板同一张表 —— 扩展进程一个字的界面文案都不需要。
//   providers.gen   引擎注册表（id / 端点 / 默认模型 / 能力），**生成物，跟 flavor 走**
//   langs.gen       语言注册表，同上
//   engine-state    needsSetup / resolve —— 与设置页、Mac 面板同一个判据
//   notes           resolveConfig（引擎三元组的唯一解析处）
//   target-lang     「译成」的解析（跟随界面语言时的回落）
//   wire-format     地址 → 传输格式（刻意无依赖）
//   request-shape   发哪些可选字段（查表，不试探）
//   translation-api 四种传输 + 停机码 + 重试
//   ext-entry       MTExt.translate，最后一个
const MODULES = [
  'app/ext-shim.js',
  'extension/content/providers.gen.js',
  'extension/content/langs.gen.js',
  'extension/content/engine-state.js',
  'extension/learn/notes.js',
  'app/target-lang.js',
  'extension/content/wire-format.js',
  'extension/content/request-shape.js',
  'extension/content/translation-api.js',
  'app/ext-entry.js',
];

// 与 app-bundle 同一条纪律：**只重定向生成物**。中国版那一份注册表只覆盖到
// `dist-china/content/`，这里照旧读 `extension/` 的话，扩展拿到的就是国际版注册表 ——
// 而它旁边的中国版 App 早把那些引擎滤掉了。缺了就报错，**不回落**：回落正是
// 「拿到了另一个 flavor 的东西，而全程没有一行警告」那个 bug 的形状。
const GENERATED = new Set(['i18n-messages.js', 'providers.gen.js', 'langs.gen.js']);


// 弹层里的文案。**唯一登记处仍然是 `extension/_locales`** —— 扩展读不到那些 JSON
// （裁剪包里没有 i18n-messages.js：整份 1 MB，而这个扩展只肯用 18 MB），所以这里把它
// 需要的那几十个键挑出来，按语种出一份小表打进扩展 bundle。
//
// 抄第二份的那天，就是两套说法开始漂的那天。上一版把中英两语写死在 ExtCopy.swift 里，
// 而共用的那几句（auth / grant_err_*）在产品别处早就有 12 个语种 —— 两处各写一套的结果
// 是同一件事在 Mac 面板上和 iPhone 弹层上说得不一样。
//
// 键分两类：**共用的**（auth_err_key / grant_err_* —— 与 Mac 快速翻译面板逐字相同）
// 与**弹层独有的**（sys_fail_* / sys_ui_* / sys_disclose_*）。
const COPY_KEYS = [
  // 停机码 → 文案。左边是 translation-api / ext-entry 会给出的码。
  'auth_err_key', 'grant_err_exhausted', 'grant_err_unavailable', 'grant_err_misconfigured',
  'grant_err_revoked', 'grant_err_invalid', 'grant_err_model', 'grant_err_busy',
  'sys_fail_network', 'sys_fail_timeout', 'sys_fail_http', 'sys_fail_no_base',
  'sys_fail_unknown_provider', 'sys_fail_needs_setup', 'sys_fail_not_synced',
  'sys_fail_empty', 'sys_fail_empty_result', 'sys_fail_engine', 'sys_fail_unknown',
  // 按钮与提示
  'sys_ui_translating', 'sys_ui_slow', 'sys_ui_replace', 'sys_ui_open_app',
  'quick_retry', 'quick_copy', 'extob_finish',
  // 首次披露（Gate J-2）。两句并列：自带 key 直连 / 免费额度经我们中转。
  'sys_disclose_direct', 'sys_disclose_grant',
];

// `_locales` 的目录名（zh_CN）→ 系统的语言码（zh-Hans）。与 sync-app-assets.js 的
// PLIST_L10N 同一张对照，理由也一样：`Locale.preferredLanguages` 给的是后者。
const LPROJ = { zh_CN: 'zh-Hans', zh_TW: 'zh-Hant', pt_BR: 'pt-BR' };

function buildExtCopy(outDir, log) {
  const root = path.join(ROOT, 'extension', '_locales');
  const out = {};
  const missing = [];
  for (const dir of fs.readdirSync(root)) {
    const f = path.join(root, dir, 'messages.json');
    if (!fs.existsSync(f)) continue;
    const m = JSON.parse(fs.readFileSync(f, 'utf8'));
    const lang = LPROJ[dir] || dir;
    const rows = {};
    for (const k of COPY_KEYS) {
      const v = m[k] && m[k].message;
      if (!v) { missing.push(`${dir}/${k}`); continue; }
      rows[k] = v;
    }
    out[lang] = rows;
  }
  // 硬失败。少一个语种的一个键，表现是那一格在弹层里是空白 —— 而空白不报错。
  if (missing.length) {
    throw new Error('ext copy: _locales 缺 ' + missing.slice(0, 8).join(' / ')
      + (missing.length > 8 ? ` …共 ${missing.length} 处` : ''));
  }
  const json = JSON.stringify(out);
  fs.writeFileSync(path.join(outDir, 'ExtCopy.json'), json);
  if (log) log(`  ✓ ExtCopy.json（${Object.keys(out).length} 语种 × ${COPY_KEYS.length} 键，${Math.round(json.length / 1024)} KB）`);
  return json.length;
}

function buildExtBundle(outDir, log, opts) {
  opts = opts || {};
  fs.mkdirSync(outDir, { recursive: true });

  const srcFor = (rel) => {
    if (!opts.genRoot) return path.join(ROOT, rel);
    const base = path.basename(rel);
    if (!rel.startsWith('extension/content/') || !GENERATED.has(base)) return path.join(ROOT, rel);
    const alt = path.join(opts.genRoot, 'content', base);
    if (!fs.existsSync(alt)) throw new Error(`ext bundle: genRoot 里缺 content/${base}（${alt}）`);
    return alt;
  };

  const parts = [
    '// GENERATED by build/ext-bundle.js — do not edit.',
    '// Sources: ' + MODULES.join(', '),
    '',
  ];
  for (const rel of MODULES) {
    const abs = srcFor(rel);
    if (!fs.existsSync(abs)) {
      // 硬失败。少一个模块出来的包会加载成功、第一次用时才抛 —— 那是最难回溯到构建的
      // 失败形状（App 包那边踩过：表现为「打开就是白屏」）。
      throw new Error(`ext bundle: missing source ${rel}`);
    }
    parts.push(`// ─── ${rel} ${'─'.repeat(Math.max(0, 60 - rel.length))}`);
    parts.push(fs.readFileSync(abs, 'utf8'));
    parts.push('');
  }

  const out = parts.join('\n');
  fs.writeFileSync(path.join(outDir, 'ExtEngine.js'), out);
  if (log) log(`  ✓ ExtEngine.js（${MODULES.length} 个模块，${Math.round(out.length / 1024)} KB）`);
  buildExtCopy(outDir, log);
  return out.length;
}

module.exports = { buildExtBundle, buildExtCopy, MODULES, COPY_KEYS, LPROJ };
